css:
/* TACT : disposition tactile proposée pour METAL (prototype injecté par layout.mjs ; valeurs à reprendre dans src/style.css).
   Unité u = diamètre des boutons secondaires (>= 48 px), tir f = 1,5 u, anneaux r1 et r2 autour du centre du tir. */
body.touch{--u:clamp(48px,14.4vmin,58px);--f:calc(var(--u)*1.5);--g:8px;--r1:calc(var(--f)/2 + var(--u)/2 + var(--g));--r2:calc(var(--r1) + var(--u) + var(--g));
  --sl:env(safe-area-inset-left,0px);--sr:env(safe-area-inset-right,0px);--sb:env(safe-area-inset-bottom,0px);--st:env(safe-area-inset-top,0px);--chip:56px;
  --cxr:calc(max(16px,var(--sr)) + var(--f)/2 + 10px);--cyb:calc(max(8px,var(--sb)) + var(--chip) + 12px + var(--f)/2)}
@media(orientation:landscape){body.touch{--cyb:calc(max(8px,var(--sb)) + 8px + var(--f)/2)}}
body.touch #touch-controls button{position:absolute!important;border-radius:50%!important;width:var(--u)!important;height:var(--u)!important;left:auto!important;top:auto!important;font-size:10px!important;letter-spacing:.4px!important;touch-action:none;pointer-events:auto}
body.touch #touch-controls #fire-button{width:var(--f)!important;height:var(--f)!important;right:calc(var(--cxr) - var(--f)/2)!important;bottom:calc(var(--cyb) - var(--f)/2)!important}
body.touch #left-fire-button{right:calc(var(--cxr) + var(--r1) - var(--u)/2)!important;bottom:calc(var(--cyb) - var(--u)/2)!important}
body.touch #jump-button{right:calc(var(--cxr) + var(--r1)*.6428 - var(--u)/2)!important;bottom:calc(var(--cyb) + var(--r1)*.766 - var(--u)/2)!important;background:#1424219c;border:1px solid #b7d0be66;color:#c6e5c1}
body.touch #dash-button{right:calc(var(--cxr) - var(--r1)*.1736 - var(--u)/2)!important;bottom:calc(var(--cyb) + var(--r1)*.9848 - var(--u)/2)!important}
body.touch #melee-button{right:calc(var(--cxr) + var(--r2)*.9781 - var(--u)/2)!important;bottom:calc(var(--cyb) + var(--r2)*.2079 - var(--u)/2)!important}
body.touch #pulse-button{right:calc(var(--cxr) + var(--r2)*.5299 - var(--u)/2)!important;bottom:calc(var(--cyb) + var(--r2)*.848 - var(--u)/2)!important}
body.touch #move-zone{left:max(20px,calc(var(--sl) + 12px))!important;bottom:calc(var(--cyb) - var(--f)/2)!important;width:112px!important;height:112px!important}
body.touch .touch-move-label,body.touch .touch-look-label{display:none!important}
/* HUD : le bas de l'écran appartient aux pouces ; arsenal en tiroir, vie et arme en pastilles de 56 px */
body.touch #arsenal{display:none!important}
body.touch .hud-bottom{display:flex!important;left:50%!important;right:auto!important;transform:translateX(-50%);bottom:max(8px,var(--sb))!important;gap:8px!important;align-items:stretch!important;width:max-content!important}
body.touch #health-panel,body.touch #weapon-readout{height:var(--chip)!important;width:auto!important;min-width:0!important;max-width:none!important;padding:4px 12px!important;overflow:hidden;display:flex!important;align-items:center;gap:8px}
body.touch #health-panel>.stat-label,body.touch #health-state,body.touch #armor-rating,body.touch #health-panel>.bar{display:none!important}
body.touch .vital strong{font-size:26px!important}
body.touch #weapon-readout .equipped-label,body.touch #weapon-readout .heat-caption,body.touch #weapon-readout .ability-strip,body.touch #weapon-readout>.bar{display:none!important}
body.touch #weapon-switch{min-height:48px!important;width:auto!important;padding:0 4px!important}
body.touch .ammo-readout>strong{font-size:24px!important}
body.touch .ammo-readout{margin:0!important}
body.touch .icon-button{width:48px!important;height:48px!important}
body.touch .hud-top{left:max(18px,var(--sl))!important;right:max(18px,var(--sr))!important;top:max(12px,var(--st))!important}
body.touch #radar-wrap{right:max(16px,var(--sr))!important;translate:0 16px}
body.touch .objective{left:max(18px,var(--sl))!important;translate:0 16px}
body.touch #wave-status{translate:0 16px}
body.touch #interact-button{min-height:48px!important;left:max(16px,var(--sl))!important;right:auto!important;transform:none!important;bottom:auto!important;top:calc(50% + 44px)!important}
@media(orientation:landscape){body.touch #interact-button{left:50%!important;transform:translateX(-50%)!important;top:auto!important;bottom:calc(max(8px,var(--sb)) + var(--chip) + 12px)!important}body.touch #direction{bottom:auto!important;top:calc(50% + 30px)!important}}
body.touch .hud-bottom{max-width:calc(100vw - 24px)!important}
body.touch #health-max,body.touch .ammo-readout>span,body.touch #armor-cap{display:none!important}
body.touch #health-panel{max-width:128px!important}body.touch #weapon-readout{max-width:176px!important}
@media(orientation:portrait){body.touch .score-status{top:calc(max(12px,var(--st)) + 56px)!important;right:auto!important;left:max(18px,var(--sl))!important;transform:none!important;align-items:flex-start!important}body.touch .objective{translate:0 44px}}
